      next_state = WORKER_IDLE_0;
    end
    if (next_state_worker_timeout_en) begin
      next_state = WORKER_TIMEOUT;
    end
  end

  // Unified Multiplexer for LHS: observed
  // Delayed pulse logic for: observed (<1, exact Q+1)
  always_ff @(posedge bus_clk) begin
    if (!bus_rst_n) begin
      observed <= 1'b0;
      observed_pulse_delay_pipe <= 1'b0;
    end else begin
      observed <= 1'b0;
      if (observed_pulse_delay_pipe) begin
        observed <= 1'b1;
      end
      observed_pulse_delay_pipe <= observed_1_en;
    end
  end

  // Unified Multiplexer for LHS: worker_done
  // Delayed pulse logic for: worker_done (<1, exact Q+1)
  always_ff @(posedge bus_clk) begin
    if (!bus_rst_n) begin
      worker_done <= 1'b0;
      worker_done_pulse_delay_pipe <= 1'b0;
    end else begin
      worker_done <= 1'b0;
      if (worker_done_pulse_delay_pipe) begin
        worker_done <= 1'b1;
      end
      worker_done_pulse_delay_pipe <= worker_done_1_en;
    end
  end

  // Unified Multiplexer for LHS: worker_wd
  // Unified flop with mux for: worker_wd (register_out assignment)
  always_comb begin
    worker_wd_next = worker_wd;  // Default value
    if (worker_wd_expr_en) begin
      worker_wd_next = 65535 - 1;
    end
    if (worker_wd_expr_2_en) begin
      worker_wd_next = worker_wd - 1;
    end
  end
  always_ff @(posedge bus_clk) begin
    if (!bus_rst_n) begin
      worker_wd <= 16'b0000000000000000;
    end else begin
      worker_wd <= worker_wd_next;
    end
  end

  `ifndef SYNTHESIS
  always_comb begin
    assert ($onehot0({worker_done_2_next_state_worker_done_ready_en, worker_timeout_next_state_worker_done_ready_en})) else $error("selector same-value conflict: next_state WORKER_DONE_READY");
    assert ($onehot0({next_state_worker_await_1_en, next_state_worker_done_2_en, next_state_worker_done_ready_en, next_state_worker_done_req_en, next_state_worker_idle_0_en, next_state_worker_timeout_en})) else $error("selector multi-value conflict: next_state");
    assert ($onehot0({worker_wd_expr_en, worker_wd_expr_2_en})) else $error("selector multi-value conflict: worker_wd");
  end
  `endif
  // Shared-datapath source-enable exports
  assign shared_dp_export_observed_1_en = observed_1_en;
  assign shared_dp_export_worker_done_1_en = worker_done_1_en;
endmodule


module activation_ready__cdc_activation_worker_start (
    input wire source_clk,
    input wire source_reset,
    input wire dest_clk,
    input wire dest_reset,
    input wire request,
    output wire ready,
    output reg pulse
);

    reg source_toggle = 1'b0;
    reg source_ack_sync_1 = 1'b0;
    reg source_ack_sync_2 = 1'b0;
    reg dest_req_sync_1 = 1'b0;
    reg dest_req_sync_2 = 1'b0;
    reg dest_seen_toggle = 1'b0;
    reg dest_ack_toggle = 1'b0;
    reg source_dest_reset_sync_1 = 1'b1;
    reg source_dest_reset_sync_2 = 1'b1;
    reg dest_source_reset_sync_1 = 1'b1;
    reg dest_source_reset_sync_2 = 1'b1;

    assign ready = (source_ack_sync_2 == source_toggle) && (!source_dest_reset_sync_2);

    always @(posedge source_clk) begin
        if (!source_reset) begin
            source_toggle <= 1'b0;
            source_ack_sync_1 <= 1'b0;
            source_ack_sync_2 <= 1'b0;
            source_dest_reset_sync_1 <= 1'b1;
            source_dest_reset_sync_2 <= 1'b1;
        end else begin
            source_dest_reset_sync_1 <= !dest_reset;
            source_dest_reset_sync_2 <= source_dest_reset_sync_1;
            if (source_dest_reset_sync_2) begin
                source_toggle <= 1'b0;
                source_ack_sync_1 <= 1'b0;
                source_ack_sync_2 <= 1'b0;
            end else begin
                source_ack_sync_1 <= dest_ack_toggle;
                source_ack_sync_2 <= source_ack_sync_1;
                if (request && ready) begin
                    source_toggle <= ~source_toggle;
                end
            end
        end
    end

    always @(posedge dest_clk) begin
        if (!dest_reset) begin
            dest_req_sync_1 <= 1'b0;
            dest_req_sync_2 <= 1'b0;
            dest_seen_toggle <= 1'b0;
            dest_ack_toggle <= 1'b0;
            pulse <= 1'b0;
            dest_source_reset_sync_1 <= 1'b1;
            dest_source_reset_sync_2 <= 1'b1;
        end else begin
            dest_req_sync_1 <= source_toggle;
            dest_req_sync_2 <= dest_req_sync_1;
            pulse <= 1'b0;
            dest_source_reset_sync_1 <= !source_reset;
            dest_source_reset_sync_2 <= dest_source_reset_sync_1;
            if (dest_source_reset_sync_2) begin
                dest_seen_toggle <= dest_req_sync_2;
                dest_ack_toggle <= dest_req_sync_2;
            end else if (dest_req_sync_2 != dest_seen_toggle) begin
                dest_seen_toggle <= dest_req_sync_2;
                dest_ack_toggle <= dest_req_sync_2;
                pulse <= 1'b1;
            end
        end
    end
endmodule


