    wire shared_dp_unused_core_shared_dp_export_worker_start_1_en;
    wire shared_dp_unused_bus_instance_shared_dp_export_observed_1_en;
    wire shared_dp_unused_bus_instance_shared_dp_export_worker_done_1_en;

    activation_ready__domain_core core (
        .clk(clk),
        .rst_n(rst_n),
        .done(done),
        .start(start),
        .worker_done(comp_link_worker_activation_done_cdc_pulse),
        .worker_start(comp_link_core_worker_start),
