        .shared_dp_export_worker_start_1_en(shared_dp_unused_core_shared_dp_export_worker_start_1_en)
    );

    activation_ready__domain_bus bus_instance (
        .bus_clk(bus_clk),
        .bus_rst_n(bus_rst_n),
